  'simple.taxes.step3.quarterly': 'Total तिमाही की फ़ाइलें महीने-दर-महीने तैयार करता है — हर महीने की एक फ़ाइल, तीनों एक फ़ोल्डर में। तिमाही रिटर्न के लिए इन्हें कैसे अपलोड करना है, यह अपने CA से पूछें।',
