  'simple.taxes.step4.b': 'GSTR-1: Prepare Offline चुनें, Total की तैयार की हुई GSTR-1 फ़ाइल अपलोड करें, फिर OTP (EVC) या अपने डिजिटल सिग्नेचर (DSC) से सबमिट करके भरें।',
