  'simple.ai.title': 'AI मददगार',
  'simple.ai.intro': 'Total ऐसी AI सेवा इस्तेमाल कर सकता है जिसका पैसा आप अलग से देते हैं, ताकि उन सवालों के जवाब मिल सकें जिनका जवाब Total खुद नहीं दे सकता। जब तक आप इसे चालू न करें, कुछ नहीं भेजा जाता।',
  'simple.ai.optional': 'आपको इसकी ज़रूरत नहीं: Total और Total से पूछें, इसके बिना पूरी तरह चलते हैं।',
