  'simple.ai.notice.masked': 'क्या छिपाया जाता है: कुछ भी भेजने से पहले GST, PAN और बैंक नंबर छिपा दिए जाते हैं (आप इसे नीचे बदल सकते हैं)।',
  'simple.ai.notice.notMasked': 'क्या छिपाया जाता है: कुछ नहीं — GST, PAN और बैंक नंबर जैसे हैं वैसे ही भेजे जाते हैं, क्योंकि नीचे छिपाना बंद है।',
  'simple.ai.notice.where': 'कहाँ जाता है: OpenAI को, आपकी अपनी key से। आपका हिसाब और बैकअप इसी कंप्यूटर पर रहते हैं; किसी बिल की फ़ाइल तभी जाती है जब आप AI से उसे पढ़वाना चुनें।',
  'simple.ai.notice.readFull': 'पूरी सूचना पढ़ें',
  'simple.ai.notice.full1': 'AI मददगार अपनी मर्ज़ी की चीज़ है और जब तक आप इसे यहाँ चालू न करें, बंद रहता है। Total इसके बिना भी चलता रहता है।',
  'simple.ai.notice.full2': 'जब आप सवाल पूछते हैं, यह कंप्यूटर आपका सवाल, अब तक की बातचीत, और AI सेवा जिन रिपोर्टों को देखती है उनके नतीजे (जैसे किसी खाते का इतिहास, या आपका बिज़नेस कैसा चल रहा है) आपकी अपनी key से OpenAI को भेजता है। पैसे देकर इस्तेमाल के OpenAI के नियम लागू होते हैं। Total OpenAI से कहता है कि वह बातचीत न रखे।',
  'simple.ai.notice.full3': 'इस कंप्यूटर से और कुछ बाहर नहीं जाता: न बैकअप, न दूसरे बिज़नेस, न फ़ाइलें — सिवाय उस बिल के जिसे आप AI से पढ़वाना चुनें (Total पहले खर्च दिखाकर पूछता है; फ़ोटो या स्कैन पर लिखे नंबर छिपाए नहीं जा सकते)।',
  'simple.ai.notice.full4': 'GST, PAN, बैंक खाता और IFSC नंबर अपने आप छिपे रहते हैं। आप ग्राहकों और सप्लायरों के नाम भी छिपा सकते हैं (वे Party-0001 वगैरह के रूप में भेजे जाते हैं, और आपको असली नामों के साथ दिखाए जाते हैं)।',
  'simple.ai.notice.full5': 'AI मददगार सिर्फ़ आपका हिसाब पढ़ता है और आपके देखने के लिए एंट्री तैयार करता है। यह कभी न कुछ सेव करता है, न बदलता है, न हटाता है — सेव आप खुद करते हैं।',
  'simple.ai.notice.full6': 'भेजा गया हर सवाल पूरे ऐप में (सेटिंग्स → AI) उसके साइज़ और खर्च के साथ दिखता है।',
